 "content": "def transform(grid):
    h, w = len(grid), max(map(len, grid))
    # Locate the separator whose removal leaves two equally sized panels.
    candidates = []
    for c in range(w):
        if all(len(row) > c for row in grid) and len({row[c] for row in grid}) == 1:
            left_w, right_w = c, min(len(row) for row in grid) - c - 1
            if left_w == right_w:
                candidates.append(("col", c))
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and r == h - r - 1:
            candidates.append(("row", r))
    if len(candidates) != 1:
        raise ValueError("expected one equal-panel separator")
    axis, k = candidates[0]
    if axis == "col":
        a = [row[:k] for row in grid]
        b = [row[k + 1:k + 1 + k] for row in grid]
        return [[3 if a[r][c] == 4 and b[r][c] == 4 else 4
                 for c in range(k)] for r in range(h)]
    a, b = grid[:k], grid[k + 1:k + 1 + k]
    width = min(min(map(len, a)), min(map(len, b)))
    return [[3 if a[r][c] == 4 and b[r][c] == 4 else 4
             for c in range(width)] for r in range(k)]
